entries[121411] = { ["name"] = "Blutroter Sturm", ["text"] = "45 Energie / 1 zu 5 Combopunkte\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der alle Gegner innerhalb von 10 Metern aufschlitzt und die Ziele bluten lässt. Dauert pro Combopunkt länger an.\n\nVerursacht zusätzlichen Schaden, wenn mehrere Gegner betroffen sind, der sich pro Ziel um 20% erhöht, bis maximal 100%.\n\nFügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n\n1 Punkt: [(60% der Angriffskraft) + (((60% der Angriffskraft) - (30% der Angriffskraft)) * (0.5))] Schaden im Verlauf von 6 Sek.\n2 Punkte: [(60% der Angriffskraft) + (((60% der Angriffskraft) - (30% der Angriffskraft)) * (1))] Schaden im Verlauf von 8 Sek.\n3 Punkte: [(60% der Angriffskraft) + (((60% der Angriffskraft) - (30% der Angriffskraft)) * (1.5))] Schaden im Verlauf von 10 Sek.\n4 Punkte: [(60% der Angriffskraft) + (((60% der Angriffskraft) - (30% der Angriffskraft)) * (2))] Schaden im Verlauf von 12 Sek.\n5 Punkte: [(60% der Angriffskraft) + (((60% der Angriffskraft) - (30% der Angriffskraft)) * (2.5))] Schaden im Verlauf von 14 Sek.\n[ 6 Punkte: [(60% der Angriffskraft) + (((60% der Angriffskraft) - (30% der Angriffskraft)) * 3)] Schaden im Verlauf von 16 Sek.] [ Meisterlicher Stratege : 7 Punkte: [(60% der Angriffskraft) + (((60% der Angriffskraft) - (30% der Angriffskraft)) * 3.5)] Schaden im Verlauf von 18 Sek ]" }
